nodes.statement:
There exists a mapping
 $
  \mathcal{B}: ~ \Omega^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.5}{\!}I_{\scalebox{0.45}{\!n}}}_{\mathcal{E}}  \to   \Omega^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.5}{\!}I_{\scalebox{0.45}{\!n}}}_{\mathcal{I}}  \text{ such that }
 $
 \begin{subequations}
 \begin{enumerate}
  \item The number of exterior elements mapped onto $T \in \Omega^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.5}{\!}I_{\scalebox{0.45}{\!n}}}_{\mathcal{I}}$  is bounded

  \begin{equation}
   \# \{ \mathcal{B}^{-1} (T) \} \leq C \quad \textnormal{for }\ T \in \Omega^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.5}{\!}I_{\scalebox{0.45}{\!n}}}_{\mathcal{I}}. 
  \end{equation}
  \item For $T \in \Omega^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.5}{\!}I_{\scalebox{0.45}{\!n}}}_{\mathcal{E}} \backslash \Omega^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.5}{\!}I_{\scalebox{0.45}{\!n}}}_{\mathcal{I}}$, there exists a path $\{T_i\}_{i=0}^M$ between $T_0 = T$ and $T_M = \mathcal{B}(T)\in \Omega^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.5}{\!}I_{\scalebox{0.45}{\!n}}}_{\mathcal{I}}$ across the set of facet $\mathcal{F}^n_T$ such that $\mathcal{F}^n_T \subseteq \mathcal{F}^{n}_R$.
  \item Moreover, the maximum occurences of a facet in the paths of $\mathcal{B}$ which we denote by
  $N_F \coloneqq \#\{ T \in \Omega^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.5}{\!}I_{\scalebox{0.45}{\!n}}}_{\mathcal{E}} \setminus \Omega^{\text{lin}\scalebox{0.3}{\!},\scalebox{0.5}{\!}I_{\scalebox{0.45}{\!n}}}_{\mathcal{I}} \mid F \in \mathcal{F}^n_T \}$ 
  is bounded:
  \begin{equation}
   \max_{F \in \mathcal{F}^n_R} N_F \leq C_{F} \left( 1 + {\Delta t}/{h}\right),
  \end{equation}
  where $C_{F}$ is independent of $\Delta t$ and $h$.
 \end{enumerate}
 \end{subequations}

Let $T_1$ and $T_2$ be the elements of the facet patch $\omega_F = T_1 \cup T_2$. Let $v = \hat v \circ (\Theta_h(\cdot, t))^{-1}$, where $\hat v$ is a piecewise polynomial of degree at most $k_s$ defined on $\omega_F$, and $t$ is a fixed time, $t \in I_n$, in a time interval $I_n$. Then there holds
 \begin{subequations}
\begin{align}
  \| D^{l_s} v \|_{\Theta_h(T_1,t)}^2 &\lesssim 
  \| D^{l_s}  v\|_{\Theta_h(T_2,t)}^2
  + 
  h^{-2l_s}\| [ v ]_{\omega_F^h} \|_{\Theta_h(T_1,t)}^2, 
   \qquad l_s \in \{0,1\}.






\end{align}
 \end{subequations}

It holds for every $u \in W_h$, $\tau \in I_n$,

\begin{align}
 \|D^{l_s} u\|^2_{Q^{h\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{E}}} &\lesssim \| D^{l_s} u \|_{Q^{h\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{I}}}^2 + \frac{h^{2-2l_s}}{\gamma_J} j^n_h(u,u), \qquad l_s \in \{0,1\},  




\end{align}

For any $u \in W_h$, it holds
\begin{align}
 \Vert u^{n-1}_+\Vert^2_{\Omega^{h}(t_{n-1}\!)} \!+\! \Vert u^n_-\Vert^2_{\Omega^{h}(t_n)} &\lesssim \frac{1}{\Delta t} \|u\|_{Q^{h\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{E}}}^2 

	\leq  \frac{ C_{lemma_bound_tn_ag_temporal_vol}  }{\Delta t} \left( \|u\|_{Q^{h\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{I}}}^2 \!+\! \frac{h^2}{\gamma_J} j^n_h(u,u) \! \right) \!\!\! 
\end{align}

For any $u \in W_h$, it holds
\begin{equation}
 \Delta t \Vert D^{l_s} \partial_t^\Theta u \Vert^2_{Q^{h\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{E}}} \lesssim \frac{ C_{lemma_temporal_inverse_ineq_gp} }{\Delta t} \left( \| D^{l_s} u \|_{Q^{h\scalebox{0.3}{\!},\scalebox{0.3}{\!}n}_{\mathcal{I}}}^2 + \frac{h^{2-2l_s}}{\gamma_J} j^n_h(u,u) \right), ~l_s\in\{0,1\}.
\end{equation}

For sufficiently small $h$ and $\Delta t$, there holds for all $u\in W_h$






\begin{align}
\Delta t^2 |\!|\!| \partial_t^\Theta  u |\!|\!|_J^2 & \leq C_{lemP35}  \left( |\!|\!| u |\!|\!|_J^2 + \gamma_J (h+\Delta t) \| \nabla u \|_{Q^h}^2 \right) .  

\end{align}

For all $u,v \in H^1(\bigcup_{n=1}^N Q^{h\scalebox{0.3}{\!},\scalebox{0.3}{\!}n})$ there is
\begin{subequations}
\vspace*{-0.2cm}\begin{equation}

| B_h(u,\!v) \!- B_{mc}(u,\!v)| \!\leq\! \int_0^T \!\!\!\int_{\partial \Omega^h(t)} \!\!\!\!\!\!\!\!\! 
| \vec{w} \cdot\! n_{\partial \Omega^h} \!-\! \mathcal{V}_h| 
uv \, \mathrm{ds} \, \mathrm{d}t 




\vspace*{-0.2cm}
\end{equation}
	where $\mathcal{V}_h$ is the velocity in the direction $n_{\partial \Omega_h}$ that describes the motion of the \emph{discrete} geometry. Furthermore, there is a constant $C_{lemma\_B\_Bmc\_diff}$ (depending on $\| \vec{w} \|_{W^{1,\infty}} < \infty$) such that
\begin{equation}
 \Vert \vec{w} \cdot\! n_{\partial \Omega^h} \!-\! \mathcal{V}_h \Vert_{L^\infty(\partial_s Q^h)} \leq C_{lemma_B_Bmc_diff} \left(h^{q_s} + \Delta t^{q_t}\right)
\end{equation}
\end{subequations}

For all $u \in W_h$ there holds

 \begin{equation}
  B_h(u,u) \geq \frac12 \left\Vert u \right\Vert^2

  - \frac{C_{lemma_B_Bmc_diff}}{2} (h^{q_s} + \Delta t^{q_t}) \cdot |\!|\!| u |\!|\!|^2. 
 \end{equation}

For all $u \in \tilde{W}_h$, there exists a $\tilde v(u) \in \tilde{W}_h$ such that
\begin{equation}
 (B_h+J)(u, \tilde v(u)) \geq C_{\text{stab}} |\!|\!| u |\!|\!|_j \cdot |\!|\!| \tilde v(u) |\!|\!|_j.
\end{equation}

There exists a constant $C_{lemma\_P37}$, independent of $h$ and $\Delta t$, such that for any $u \in \tilde{W}_h$ and $h$ and $\Delta t$ sufficiently small there holds
\begin{align}
 &(B_h+J)(u, \tilde\Pi(\Delta t \partial_t^\Theta u)) 


 \geq \frac{\Delta t}{2}   \Vert \partial_t^\Theta u \Vert_{Q^{h}}^2 \!-\! C_{lemma_P37} \left\Vert u \right\Vert_j^2 



\end{align}

For all $u \in W_h$, there holds for sufficiently small mesh sizes $h$ and time steps $\Delta t$ that 
\begin{equation}
 |\!|\!| \tilde\Pi(\Delta t \partial_t^\Theta u) |\!|\!|_j \lesssim |\!|\!| u |\!|\!|_j. 
\end{equation}
